text.main.ts:
// game initialization
tiles.setCurrentTilemap(tilemap`level1`)

let facingRight = true
let swimming = false

let bearSprite = sprites.create(assets.image`walkBearRight`, SpriteKind.Player)
scene.cameraFollowSprite(bearSprite)
controller.moveSprite(bearSprite, 100, 0)
bearSprite.setStayInScreen(true)
bearSprite.ay = 500
bearSprite.z = 3

function startGame() {
    facingRight = true
    swimming = false
    tiles.placeOnTile(bearSprite, tiles.getTileLocation(0, 0))
}

function makeSalmon() {
    let salmon = sprites.create(assets.image`salmonImage`, SpriteKind.Food)
    tiles.placeOnTile(salmon, tiles.getTileLocation(19, randint(5, 18)))
    salmon.vx = randint(-75, -25)
    salmon.setFlag(SpriteFlag.DestroyOnWall, true)
}

function spriteImage(isFacingRight: boolean, isSwimming: boolean) {
    if (isFacingRight) {
        bearSprite.setImage(assets.image`walkBearRight`)
    } else if (isFacingRight) {
        bearSprite.setImage(assets.image`swimBearRight`)
    } else if (!isFacingRight) {
        bearSprite.setImage(assets.image`walkBearLeft`)
    } else if (!isFacingRight) {
        bearSprite.setImage(assets.image`swimBearLeft`)
    }
}

// game start
startGame()

// game events
game.onUpdate(function () {
    spriteImage(facingRight, swimming)
})

game.onUpdateInterval(1000, function () {
    makeSalmon()
})

sprites.onOverlap(SpriteKind.Player, SpriteKind.Food, function (sprite: Sprite, otherSprite: Sprite) {
    sprites.destroy(otherSprite)
})

controller.A.onEvent(ControllerButtonEvent.Pressed, function () {
    if (swimming) {
        bearSprite.vy = -200
    }
})

controller.right.onEvent(ControllerButtonEvent.Pressed, function () {
    facingRight = true
})

controller.left.onEvent(ControllerButtonEvent.Pressed, function () {
    facingRight = false
})

scene.onOverlapTile(SpriteKind.Player, assets.tile`swimTile`, function (sprite: Sprite, location: tiles.Location) {
    swimming = true
})

scene.onOverlapTile(SpriteKind.Player, assets.tile`skyTile`, function (sprite: Sprite, location: tiles.Location) {
    swimming = false
})
